script:
// One @, something before and after it, and a domain ending of two letters or more.
var e = email.trim();
return e =~ '^[^ @]+@[^ @]+[.][A-Za-z]{2,}$';

var p = phone.trim();
if (!(p =~ '^[+]?[0-9 ()-]+$')) {
  return false;
}
var digits = p.replaceAll('[^0-9]', '');
return digits.length() >= 8 && digits.length() <= 15;

var first = firstName.trim().titleCase();
var last = lastName.trim().titleCase();
if (first == '') {
  return last;
}
if (last == '') {
  return first;
}
return first + ' ' + last;

var out = '';
for (var word : name.trim().split(' ')) {
  if (word != '' && out.length() < letters) {
    out = out + word.substring(0, 1).upper();
  }
}
return out;

var e = email.trim();
var at = e.indexOf('@');
if (at < 1) {
  return e;
}
return e.substring(0, 1) + '***' + e.substring(at);

var words = text.trim().replaceAll('[^A-Za-z0-9]+', ' ').trim();
if (words == '') {
  return 0;
}
return words.split(' ').count();

if (from == 0) {
  return null;
}
return ((to - from) / from.abs() * 100).round(places);

var net = inclusive ? amount / (1 + rate) : amount;
var tax = net * rate;
return {'net': net.round(2), 'tax': tax.round(2), 'gross': (net + tax).round(2)};

var subtotal = 0;
var items = 0;
for (var line : lines) {
  var qty = (line.qty ?? 1).toNumber();
  subtotal = subtotal + qty * line.price.toNumber();
  items = items + qty;
}
var discount = subtotal * discountPercent / 100;
var tax = (subtotal - discount) * taxRate;
return {
  'items': items,
  'subtotal': subtotal.round(2),
  'discount': discount.round(2),
  'tax': tax.round(2),
  'total': (subtotal - discount + tax).round(2)
};

var on = onDate == null ? today() : onDate;
var years = on.formatDate('yyyy').toNumber() - birthday.formatDate('yyyy').toNumber();
if (on.formatDate('MMdd').toNumber() < birthday.formatDate('MMdd').toNumber()) {
  years = years - 1;
}
return years;

var from = start;
var to = end;
var sign = 1;
if (daysBetween(start, end) < 0) {
  from = end;
  to = start;
  sign = -1;
}
var total = daysBetween(from, to) + 1;
var dow = lookup({'Mon': 1, 'Tue': 2, 'Wed': 3, 'Thu': 4, 'Fri': 5, 'Sat': 6, 'Sun': 7}, from.formatDate('EEE'), 1);
var count = (total / 7).floor() * 5;
var rest = total % 7;
if (rest > 0) {
  for (var i : 0 .. (rest - 1)) {
    if ((dow - 1 + i) % 7 < 5) {
      count = count + 1;
    }
  }
}
return count * sign;

var dow = lookup({'Mon': 1, 'Tue': 2, 'Wed': 3, 'Thu': 4, 'Fri': 5, 'Sat': 6, 'Sun': 7}, date.formatDate('EEE'), 1);
var d = date;
if (days > 0 && dow > 5) {
  // From a weekend, count from the Friday before it.
  d = d.subtractDays(dow - 5);
  dow = 5;
}
var weeks = (days / 5).floor();
var rest = days - weeks * 5;
d = d.addDays(weeks * 7);
if (rest > 0) {
  for (var i : 1 .. rest) {
    d = d.addDays(1);
    dow = dow + 1;
    if (dow == 6) {
      d = d.addDays(2);
      dow = 1;
    }
  }
}
return d.formatDate('yyyy-MM-dd');

var on = onDate == null ? today() : onDate;
var days = daysBetween(on, date);
if (days == 0) {
  return 'today';
}
if (days == 1) {
  return 'tomorrow';
}
if (days == -1) {
  return 'yesterday';
}
return days > 0 ? 'in ' + days + ' days' : (0 - days) + ' days ago';
